    initExportMap(dayNum, containerEl) {
      if (!window.AMap || !containerEl) {
        console.warn(`第${dayNum}天地图初始化失败：缺少必要参数`);
        return;
      }

      // 销毁旧地图实例
      if (this.maps[dayNum]) {
        this.maps[dayNum].destroy();
      }

      // 获取该天的景点数据
      const day = this.routeDetail.itinerary.find(d => d.dayNum === dayNum);
      if (!day) {
        console.warn(`第${dayNum}天数据不存在`);
        return;
      }
      const attractions = this.getDayAttractions(day);
      if (attractions.length === 0) {
        console.warn(`第${dayNum}天没有景点坐标数据`);
        return;
      }
      try {
        // 确保容器尺寸正确且没有overflow隐藏
        containerEl.style.height = '400px';
        containerEl.style.width = '100%';
        containerEl.style.overflow = 'visible';

        // 创建地图实例
        // 关键修复：使用浅色主题确保底图正确渲染
        const map = new AMap.Map(containerEl, {
          zoom: 12,
          center: [attractions[0].longitude, attractions[0].latitude],
          mapStyle: 'amap://styles/light',
          resizeEnable: true,
          // 确保地图在截图时完全加载，包含所有图层
          features: ['bg', 'road', 'building', 'point'],
          crossOrigin: 'anonymous',
          // 关键修复：开启跨域支持，确保瓦片可被 html2canvas 读取
          viewMode: '3D',
          showLabel: true
        });

        // 缓存地图实例
        this.$set(this.maps, dayNum, map);

        // 提取坐标点
        const path = attractions.map(p => [p.longitude, p.latitude]);

        // 绘制路线连线
        const polyline = new AMap.Polyline({
          path: path,
          strokeColor: '#FF7A2F',
          strokeWeight: 4,
          strokeStyle: 'solid',
          lineJoin: 'round',
          lineCap: 'round'
        });
        map.add(polyline);

        // 添加标记点（含序号+名称标签）
        attractions.forEach((point, index) => {
          let offsetX = 0;
          let offsetY = 0;
          if (index > 0) {
            const prevPoint = attractions[index - 1];
            const distance = Math.sqrt(Math.pow(point.longitude - prevPoint.longitude, 2) + Math.pow(point.latitude - prevPoint.latitude, 2));
            if (distance < 0.002) {
              offsetX = (index % 2 === 0 ? 1 : -1) * 0.00015;
              offsetY = (index % 2 === 0 ? 1 : -1) * 0.00015;
            }
          }

          // 创建带序号的圆形标记
          const markerContent = `
            <div style="
              background: #FF7A2F;
              color: white;
              width: 28px;
              height: 28px;
              border-radius: 50%;
              display: flex;
              align-items: center;
              justify-content: center;
              font-size: 14px;
              font-weight: bold;
              border: 3px solid white;
              box-shadow: 0 2px 6px rgba(0,0,0,0.3);
              white-space: nowrap;
              z-index: 120;
            ">${index + 1}</div>
          `;
          const marker = new AMap.Marker({
            position: [point.longitude + offsetX, point.latitude + offsetY],
            content: markerContent,
            offset: new AMap.Pixel(-14, -14),
            zIndex: 120
          });
          map.add(marker);

          // 创建文字标签显示点位名称 - 确保在截图时可见
          const labelContent = `
            <div style="
              background: rgba(255,255,255,0.95);
              color: #333;
              padding: 4px 8px;
              border-radius: 4px;
              font-size: 12px;
              font-weight: 500;
              white-space: nowrap;
              box-shadow: 0 1px 4px rgba(0,0,0,0.15);
              border: 1px solid #e0e0e0;
              max-width: 120px;
              overflow: hidden;
              text-overflow: ellipsis;
              position: relative;
              z-index: 130;
            ">${point.name}</div>
          `;
          const labelMarker = new AMap.Marker({
            position: [point.longitude + offsetX, point.latitude + offsetY],
            content: labelContent,
            offset: new AMap.Pixel(-60, 18),
            // 偏移：水平居中，垂直在圆点下方
            zIndex: 130
          });
          map.add(labelMarker);
        });

        // 调整地图视野
        map.setFitView();

        // 确保地图完全加载和渲染
        // 关键：多次触发 resize 以确保所有瓦片加载完成
        setTimeout(() => {
          map.resize();
        }, 100);
        setTimeout(() => {
          map.resize();
        }, 500);
      } catch (error) {
        console.error(`第${dayNum}天导出地图初始化失败:`, error);
      }
    }
  }
};
